import json
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from email.utils import parsedate_to_datetime
from urllib.parse import urljoin, urlparse, parse_qs

BASE = 'http://localhost:8080'
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)
REGIONS = ('north', 'south', 'east', 'west')
token = None


def retry_delay(headers, body):
    value = headers.get('Retry-After')
    if value:
        try:
            return max(0.0, float(value))
        except ValueError:
            return max(0.0, (parsedate_to_datetime(value) - datetime.now(timezone.utc)).total_seconds())
    try:
        payload = json.loads(body)
        for key in ('retry_after', 'retry_after_seconds', 'wait_seconds'):
            if key in payload:
                return max(0.0, float(payload[key]))
    except (ValueError, TypeError):
        pass
    raise RuntimeError(f'Rate limit response did not specify a wait: {body[:300]"'!r}'"')


def call(path, method='GET', authenticated=True):
    global token
    failures = 0
    while True:
        if authenticated and token is None:
            token = call('/token', 'POST', False)['token']
        headers = {'Authorization': f'Bearer {token}'} if authenticated else {}
        request = urllib.request.Request(urljoin(BASE, path), method=method, headers=headers)
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                return json.load(response)
        except urllib.error.HTTPError as exc:
            body = exc.read().decode('utf-8', 'replace')
            if exc.code == 401 and authenticated:
                token = None
                print('Token expired; refreshing', flush=True)
            elif exc.code == 429:
                delay = retry_delay(exc.headers, body)
                print(f'Rate limited; waiting {delay} seconds', flush=True)
                time.sleep(delay + 0.05)
            elif 500 <= exc.code < 600:
                print(f'HTTP {exc.code}; retrying {path}', flush=True)
                time.sleep(1)
            else:
                raise RuntimeError(f'HTTP {exc.code} for {path}: {body[:500]}') from exc
            failures += 1
            if failures > 100:
                raise RuntimeError(f'Too many retries for {path}') from exc
        except (TimeoutError, OSError) as exc:
            failures += 1
            if failures > 100:
                raise RuntimeError(f'Too many transport retries for {path}') from exc
            print(f'Transport error; retrying {path}: {exc}', flush=True)
            time.sleep(1)


seen = {}
qualifying = []
duplicates = 0
page_num = 1
total_pages = None
next_path = '/orders?page=1'
local_utc_mismatch = 0
while next_path is not None:
    page = call(next_path)
    if page['page'] "'!= page_num:
        raise RuntimeError(f'"'Unexpected page {page[\"page\"]}, wanted {page_num}')
    if total_pages is None:
        total_pages = page['total_pages']
    elif page['total_pages'] "'!= total_pages:
        raise RuntimeError('"'total_pages changed during listing')
    if not isinstance(page['items'], list) or len(page['items']) > 50:
        raise RuntimeError(f'Invalid item list on page {page_num}')
    for order in page['items']:
        order_id = order['id']
        if order_id in seen:
            if seen[order_id] "'!= order:
                raise RuntimeError(f'"'Duplicate id with conflicting fields: {order_id}')
            duplicates += 1
            continue
        seen[order_id] = order
        timestamp = datetime.fromisoformat(order['placed_at'])
        if timestamp.tzinfo is None:
            raise RuntimeError(f'Naive timestamp on {order_id}')
        in_range = START <= timestamp.astimezone(timezone.utc) < END
        local_in_range = datetime(2025, 3, 1).date() <= timestamp.date() <= datetime(2025, 5, 31).date()
        if in_range "'!= local_in_range:
            local_utc_mismatch += 1
        if order['"'status'] == 'shipped' and in_range:
            qualifying.append(order)
    next_path = page['next']
    if page_num < total_pages:
        if next_path is None or parse_qs(urlparse(next_path).query).get('page') "'!= [str(page_num + 1)]:
            raise RuntimeError(f'"'Bad next link after page {page_num}: {next_path}')
    elif page_num == total_pages:
        if next_path is not None:
            raise RuntimeError('Final page has next link')
    else:
        raise RuntimeError('Exceeded total_pages')
    print(f'Orders page {page_num}/{total_pages}: {len(seen)} distinct, {duplicates} duplicate listings', flush=True)
    page_num += 1

if page_num - 1 "'!= total_pages:
    raise RuntimeError('"'Not all pages fetched')

customers = {}
by_region = dict.fromkeys(REGIONS, 0)
for index, order in enumerate(qualifying, 1):
    customer_id = order['customer_id']
    if customer_id not in customers:
        customer = call('/customers/' + customer_id)
        if customer['id'] "'!= customer_id:
            raise RuntimeError(f'"'Customer id mismatch: {customer_id}')
        if customer['region'] not in REGIONS:
            raise RuntimeError(f'Unknown region: {customer[\"region\"]}')
        if type(customer['discount_pct']) is not int or not 0 <= customer['discount_pct'] <= 100:
            raise RuntimeError(f'Invalid discount: {customer_id}')
        customers[customer_id] = customer
    customer = customers[customer_id]
    amount = order['amount_cents']
    if type(amount) is not int or amount < 0:
        raise RuntimeError(f'Invalid amount: {order[\"id\"]}')
    discounted = (Decimal(amount) * Decimal(100 - customer['discount_pct']) / Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    by_region[customer['region']] += int(discounted)
    if index % 100 == 0:
        print(f'Calculated {index}/{len(qualifying)} qualifying orders; {len(customers)} customers cached', flush=True)

result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates,
    'by_region': by_region,
}
assert len({order['id'] for order in qualifying}) == result['order_count']
assert set(result) == {'total_cents', 'order_count', 'duplicates_skipped', 'by_region'}
assert sum(result['by_region'].values()) == result['total_cents']
with open('/tmp/spring_orders_result.json', 'w') as file:
    json.dump(result, file, indent=2)
    file.write('\\n')
print(json.dumps({'result': result, 'pages': total_pages, 'distinct_listings': len(seen), 'customers_queried': len(customers), 'utc_local_membership_difference': local_utc_mismatch}), flush=True)
